import torch


def run(self, other):
    self.__ilshift__(other)
    return self


def _dtype_from_context(ctx, name):
    return getattr(torch, ctx[f"{name}__dtype"])


def gen_inputs(ctx, device):
    self_shape = ctx["self__shape"]
    other_shape = ctx["other__shape"]
    self_dtype = _dtype_from_context(ctx, "self")
    other_dtype = _dtype_from_context(ctx, "other")
    a = torch.randint(0, 100, self_shape, dtype=self_dtype, device="cpu").to(device)
    b = torch.randint(0, 8, other_shape, dtype=other_dtype, device="cpu").to(device)
    return {"self": a, "other": b}
